targets.expr:
sum(
  gbfs_station_vehicles_available{system=~"$system"}
    and on (system, station_id) gbfs_station_capacity{system=~"$system"}
)
/
sum(
  gbfs_station_capacity{system=~"$system"}
    and on (system, station_id) gbfs_station_vehicles_available{system=~"$system"}
)

clamp_min(
  sum(
  gbfs_station_capacity{system=~"$system"}
    and on (system, station_id) gbfs_station_vehicles_available{system=~"$system"}
)
  - sum(
  gbfs_station_vehicles_available{system=~"$system"}
    and on (system, station_id) gbfs_station_capacity{system=~"$system"}
)
  - (sum(
  gbfs_station_docks_available{system=~"$system"}
    and on (system, station_id) gbfs_station_capacity{system=~"$system"}
) or vector(0))
, 0)

sum(
  gbfs_station_vehicles_available{system=~"$system"}
    and on (system, station_id) gbfs_station_capacity{system=~"$system"}
)
/
sum(
  gbfs_station_capacity{system=~"$system"}
    and on (system, station_id) gbfs_station_vehicles_available{system=~"$system"}
)

sum by (station_id, station_name) (
  gbfs_station_vehicles_available{system=~"$system"}
    * on (system, station_id) group_left (station_name)
      gbfs_station_info{system=~"$system"}
)
